method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // lst is a non-empty list
    ensures forall i :: 0 <= i < |lst| ==> (lst[i] % 2 == 0 && i % 2 == 1 ==> result == SumEvenAtOddIndices(lst))
{
    var sum := 0;
    var i := 1;
    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant sum == SumEvenAtOddIndices(lst[..i])
    {
        if (lst[i] % 2 == 0) {
            sum := sum + lst[i];
        }
        i := i + 2; // move to the next odd index
    }
    result := sum;
}

method SumEvenAtOddIndices(lst: seq<int>) returns (sum: int)
    decreases |lst|
{
    sum := 0;
