    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant sum == SumEvenAtOddIndices(lst[..i])
    {
        if (lst[i] % 2 == 0) {
            sum := sum + lst[i];
        }
        i := i + 2; // move to the next odd index
    }
}
